"""时刻计算：更新当前站发车时间、重算后续各站时间。

需求依据见 REQ-1。
"""

from dataclasses import dataclass, field


def to_minutes(hhmm: str) -> int:
    hours, minutes = hhmm.split(":")
    return int(hours) * 60 + int(minutes)


def to_hhmm(total: int) -> str:
    return f"{total // 60 % 24:02d}:{total % 60:02d}"


@dataclass
class Train:
    """一趟车：始发时刻 + 各站间运行时分（"A->B" -> 分钟）。"""

    train_id: str
    start: str
    legs: dict[str, int] = field(default_factory=dict)

    def stops(self) -> list[str]:
        """按 leg 顺序推导站序：首站 + 各 leg 的终点。"""
        stops: list[str] = []
        for leg in self.legs:
            origin, _, destination = leg.partition("->")
            if not stops:
                stops.append(origin)
            stops.append(destination)
        return stops


def arrival_times(train: Train) -> dict[str, str]:
    """各站时刻 = 始发时刻 + 累计运行时分。"""
    stops = train.stops()
    clock = to_minutes(train.start)
    times = {stops[0]: to_hhmm(clock)}
    for index, minutes in enumerate(train.legs.values()):
        clock += minutes
        times[stops[index + 1]] = to_hhmm(clock)
    return times

"""页面/接口：选择目标站点、提交新车发时间（功能入口）。

需求依据见 REQ-4。
"""

from publish import can_publish
from schedule import Train, arrival_times


def show_timetable(train: Train) -> dict[str, str]:
    """展示各站时刻。"""
    return arrival_times(train)


def submit_publish(train: Train, fleet: list) -> tuple[bool, str]:
    """提交发布：先经占用与发布判断。"""
    return can_publish(train, fleet)

"""车辆占用检查：对照车辆其他任务检查时间窗冲突。

需求依据见 REQ-2。
"""

from dataclasses import dataclass


@dataclass
class Occupation:
    """一段车辆占用：车号 + 起止分钟。"""

    train_id: str
    start_min: int
    end_min: int


def conflicts(left: Occupation, right: Occupation) -> bool:
    """同一车辆的两段占用时间窗是否重叠。"""
    if left.train_id != right.train_id:
        return False
    return left.start_min < right.end_min and right.start_min < left.end_min


def has_conflicts(items: list[Occupation]) -> bool:
    for index, left in enumerate(items):
        for right in items[index + 1:]:
            if conflicts(left, right):
                return True
    return False

